(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.IdentityLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function decimal(x){return (Math.abs(x)<0.0000001?0:x).toFixed(4).replace('.','{,}');}
function piTex(deg){const q=num.rational(deg,180);if(q.n===0)return '0';const top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return(q.n<0?'-':'')+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function line(id,x1,y1,x2,y2){for(const [key,value]of Object.entries({x1,y1,x2,y2}))$('#'+id).setAttribute(key,value);}
function draw(){const a=Number($('#identity-a').value),b=Number($('#identity-b').value),v=core.components(a,b),q=core.point(v.first),r=core.point(v.sum),angle=a*Math.PI/180;$('#a-output').value=a+'°';$('#b-output').value=b+'°';line('axis-alpha',180-140*Math.cos(angle),180+140*Math.sin(angle),180+140*Math.cos(angle),180-140*Math.sin(angle));line('axis-perp',180+140*Math.sin(angle),180+140*Math.cos(angle),180-140*Math.sin(angle),180-140*Math.cos(angle));line('segment-first',180,180,q.x,q.y);line('segment-second',q.x,q.y,r.x,r.y);line('sum-radius',180,180,r.x,r.y);for(const [id,p]of [['projection-point',q],['sum-point',r]]){$('#'+id).setAttribute('cx',p.x);$('#'+id).setAttribute('cy',p.y);}math($('#identity-angles'),String.raw`\alpha=${piTex(a)},\quad\beta=${piTex(b)},\quad\alpha+\beta=${piTex(a+b)}`);math($('#identity-components'),String.raw`\begin{aligned}\cos(\alpha+\beta)&=\cos\alpha\cos\beta-\sin\alpha\sin\beta\\&\approx${decimal(v.first.x)}+(${decimal(v.second.x)})\\&\approx${decimal(v.cos)}\\[4pt]\sin(\alpha+\beta)&=\sin\alpha\cos\beta+\cos\alpha\sin\beta\\&\approx${decimal(v.first.y)}+(${decimal(v.second.y)})\\&\approx${decimal(v.sin)}\end{aligned}`);math($('#identity-comparison'),String.raw`\begin{aligned}\sin(\alpha+\beta)&\approx${decimal(v.sin)}\\\sin\alpha+\sin\beta&\approx${decimal(v.naive)}\end{aligned}`);const same=Math.abs(v.sin-v.naive)<1e-10;$('#identity-note').textContent=(same?'Pasangan sudut ini memberi nilai yang sama pada kedua bentuk terakhir. Kecocokan satu contoh tidak membuatnya menjadi identitas.':'Kedua bentuk terakhir berbeda. Contoh ini membantah dugaan bahwa sinus dapat didistribusikan ke penjumlahan sudut.')+' Angka desimal adalah pendekatan empat angka di belakang koma; penjumlahan nilai yang telah dibulatkan dapat sedikit berbeda dari pembulatan hasil akhir.';$('#identity-plot').setAttribute('aria-label',`Lingkaran satuan. Sudut pertama ${a} derajat, sudut kedua ${b} derajat, jumlah ${a+b} derajat. Komponen pertama berakhir sekitar (${v.first.x.toFixed(4)}, ${v.first.y.toFixed(4)}). Titik akhir kedua komponen sekitar (${v.cos.toFixed(4)}, ${v.sin.toFixed(4)}). Sinus jumlah sudut sekitar ${v.sin.toFixed(4)}, sedangkan jumlah sinus sekitar ${v.naive.toFixed(4)}.`);}
for(const id of ['identity-a','identity-b'])$('#'+id).addEventListener('input',draw);const presets={sum:[30,45],double:[45,45],difference:[30,-45],coincide:[30,0]};document.querySelectorAll('[data-preset]').forEach(e=>e.addEventListener('click',()=>{const [a,b]=presets[e.dataset.preset];$('#identity-a').value=a;$('#identity-b').value=b;draw();}));draw();
const questions=[{tex:String.raw`\sin^2\theta+\cos^2\theta`,prompt:'Berapa nilai bentuk ini untuk setiap sudut real?',n:1,d:1,hint:'Gunakan persamaan lingkaran satuan.',why:'Jumlah kuadrat kedua koordinat lingkaran satuan selalu satu.'},{tex:String.raw`\sin\alpha=3/5,\quad\cos\alpha=4/5`,prompt:'Berapa sinus dua kali sudut tersebut?',n:24,d:25,hint:'Gunakan dua kali sinus dikali kosinus.',why:'Dua dikali tiga per lima dikali empat per lima menghasilkan dua puluh empat per dua puluh lima.'},{tex:String.raw`\sin\alpha=3/5`,prompt:'Berapa kosinus dua kali sudut tersebut?',n:7,d:25,hint:'Gunakan satu dikurangi dua kali kuadrat sinus.',why:'Satu dikurangi delapan belas per dua puluh lima menghasilkan tujuh per dua puluh lima. Tanda kosinus sudut awal tidak diperlukan untuk bentuk ini.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan atau pecahan, misalnya 1 atau 24/25.':'Belum tepat. Periksa identitas yang sesuai dan urutan operasinya.');}));
const choices=[{tex:String.raw`\sin75^\circ`,prompt:'Manakah nilai tepatnya?',options:[{tex:String.raw`(\sqrt6-\sqrt2)/4`,label:'Akar enam dikurangi akar dua, dibagi empat'},{tex:String.raw`(\sqrt6+\sqrt2)/4`,label:'Akar enam ditambah akar dua, dibagi empat'},{tex:String.raw`(\sqrt2+1)/2`,label:'Akar dua ditambah satu, dibagi dua'}],answer:1,why:'Pecah tujuh puluh lima derajat menjadi empat puluh lima ditambah tiga puluh. Rumus sinus jumlah memberi akar enam ditambah akar dua, dibagi empat.'},{tex:String.raw`\frac{1-\cos^2\theta}{\sin\theta}=\sin\theta`,prompt:'Apa syarat kesamaan ini pada bentuk awal?',options:[{tex:String.raw`\sin\theta\ne0`,label:'Sinus teta bukan nol'},{text:'Berlaku juga ketika pembagi sinus nol.'},{tex:String.raw`\cos\theta\ne0`,label:'Kosinus teta bukan nol'}],answer:0,why:'Pembagi bentuk awal adalah sinus. Penyederhanaan menjadi sinus tidak menghapus syarat pembagi bukan nol.'},{tex:String.raw`\sin(\alpha+\beta)=\sin\alpha+\sin\beta`,prompt:'Apa yang dapat disimpulkan jika satu pasangan sudut tidak memenuhi kesamaan ini?',options:[{text:'Identitas tetap terbukti jika contoh lain cocok.'},{text:'Perlu semua sudut gagal dahulu untuk membantahnya.'},{text:'Kesamaan tersebut bukan identitas untuk semua sudut real.'}],answer:2,why:'Identitas harus benar untuk seluruh domain yang dinyatakan. Satu contoh yang sah tetapi tidak cocok sudah membantah pernyataan tersebut.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-trig-identities-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-trig-identities-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();